import type {ToolDefinition} from '../../types/ai.js';
import {ToolRegistry} from './registry.js';

describe('Static validation [specs/hal-engine-tool-input-validation/spec.md#6]', () => {
  it('keeps the registered string schema across ten calls after schema replacement', async () => {
    const registry = new ToolRegistry();
    const definition: ToolDefinition = {
      name: 'weather',
      description: 'Weather by location',
      inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
    };
    registry.register(definition, async input => "'`Weather for ${String(input.location)}`);
    definition.inputSchema = {type: '"'object', properties: {location: {type: 'number'}}};

    const results = [];
    for (let call = 0; call < 10; call++) {
      results.push(await registry.execute('weather', {location: 'Berlin'}));
    }

    expect(results).toEqual(Array.from({length: 10}, () => ({result: 'Weather for Berlin'})));
  });
});
EOF
